[
  {
    "id": "c001",
    "name": "Preamble",
    "text": "This Operating Agreement and Members Agreement (“Agreement”) of Dialogo, LLC (the “Company\") is made as of June __, 2004, among Lillian Santiago Bauza, a resident of Massachusetts (“LSB”), and Direct Merchants S.A., Inc., a New Jersey Corporation (\"DMSA\"), as members of the Company, and the persons or entities who become members of the Company in accordance with the provisions hereof and whose names are set forth as Members on Schedule A hereto."
  },
  {
    "id": "c002",
    "name": "Recital",
    "text": "WHEREAS, LSB and DMSA desire to form a limited liability company pursuant to the Maine Lunited Liability Company, as amended from time to time (the \"Maine Act\"), by filing Articles of Organization with the office of the Secretary of State of the State of Maine and entering into this Agreement."
  },
  {
    "id": "c003",
    "name": "Consideration",
    "text": "NOW, THEREFORE, in consideration of the agreements and obligations set forth herein and for other good and valuable consideration, the receipt and sufficiency of which are hereby acknowledged and intending to be legally bound, the Members hereby agree as follows:"
  },
  {
    "id": "c004",
    "name": "Section 1.1 Definitions",
    "text": "Section 1.1 Definitions. Unless the context otherwise requires, the terms defined in this Article I shall, for the purposes of this Agreement, have the meanings herein specified."
  },
  {
    "id": "c005",
    "name": "Definition: Additional Members",
    "text": "“Additional Members” has the meaning set forth in Section 13.1 hereof."
  },
  {
    "id": "c006",
    "name": "Definition: Affiliate",
    "text": "\"Affiliate\" means with respect to a specified Person, any Person that directly or indirectly controls, is controlled by, or is under common control with, the specified Person. As used in this definition, the term \"control\" means the possession, directly or indirectly, of the power to direct or cause the direction.of the management and policies of a Person, whether through ownership of voting secunties, by contract or otherwise."
  },
  {
    "id": "c007",
    "name": "Definition: Agreement",
    "text": "“Agreement” means this Operating Agreement and Members Agreement of the Company, as amended, modified, supplemented or restated from time to time."
  },
  {
    "id": "c008",
    "name": "Definition: Articles",
    "text": "\"Articles\" means the Articles of Organization of the Company and any and all amendments thereto and restatements thereof filed on behalf of the Company with the office of the Secretary of State of the State of Maine pursuant to the Maine Act."
  },
  {
    "id": "c009",
    "name": "Definition: Board",
    "text": "\"Board\" means the Board of Directors of the Company."
  },
  {
    "id": "c010",
    "name": "Definition: Capital Account",
    "text": "\"Capital Account\" means, with respect to any Member, the account maintained for such Member tn accordance with the provisions of Section 4.4 hereof."
  },
  {
    "id": "c011",
    "name": "Definition: Capital Contribution",
    "text": "\"Capital Contribution\" means, with respect to any Member, the aggregate amount of money and the fair market value of any property (other than money) contributed to the Company pursuant to Section 4.1 hereof with respect to such Member's Interest."
  },
  {
    "id": "c012",
    "name": "Definition: Code",
    "text": "\"Code\" means the Internal Revenue Code of 1986, as amended from time to time, or any corresponding federal tax statute enacted after the date of this Agreement. A reference to a specific section of the Code refers not only to such specific section but also to any corresponding provision of any federal tax statute enacted after the date of this Agreement, as such specific section or corresponding provision is in effect on the date of application of the provisions of this Agreement containing such reference."
  },
  {
    "id": "c013",
    "name": "Definition: Company",
    "text": "\"Company\" means Dialogo, LLC, the lumited liability company formed and continued under and pursuant to the Maine Act and this Agreement."
  },
  {
    "id": "c014",
    "name": "Definition: Covered Person",
    "text": "\"Covered Person\" means a Member, a Director, an Officer, a Manager, any Affiliate of a Member, a Director, an Officer or a Manager, any officers, directors, Members, partners, employees, representatives or agents of a Member, a Director, an Officer or a Manager, or their respective Affihates, or any employee or agent of the Company or its Affiliates."
  },
  {
    "id": "c015",
    "name": "Definition: Director",
    "text": "\"Director\" means a director of the Company."
  },
  {
    "id": "c016",
    "name": "Definition: Fiscal Year",
    "text": "\"Fiscal Year\" means (i) the period commencing upon the formation of the Company and ending on December 31, 2004, (11) any subsequent twelve (12) month period commencing on January 1 and ending on December 31, or (iii) any portion of the period described in Clause (ii) of this sentence for which the Company is required to allocate Profits, Losses and other items of Company income, gain, loss or deduction pursuant to Article VIII hereof."
  },
  {
    "id": "c017",
    "name": "Definition: Interest",
    "text": "“Interest” means a Member's limited liability company interest in the Company which represents any Member Votes held by a member and such Member's interest of the profits and losses of the Company and a Member's right to receive distributions of the Company's assets in accordance with the provisions of this Agreement and the Maine Act."
  },
  {
    "id": "c018",
    "name": "Definition: Laws",
    "text": "\"Laws\" means: (i) all constitutions, treaties, laws, statutes, codes, ordinances, orders, decrees, rules, regulations and municipal by-laws, whether domestic, foreign or international: (ii) all judgments, orders, wnts, injunctions, decisions, rulings, decrees and awards of any governmental body; (i) _ all policies, practices and guidelines of any govemmental body; and (Iv) any amendment, modification, re-enactment, restatement or extension of the foregoing, in each case binding on or affecting the party or Person referred to in the context in which such word is used; and \"Law\" shall mean any one of them."
  },
  {
    "id": "c019",
    "name": "Definition: Maine Act",
    "text": "\"Maine Act\" means the Maine Limited Liability Company Act, 31 M.R.S.A. Chapter 13, as amended from time to time."
  },
  {
    "id": "c020",
    "name": "Definition: Majority Vote",
    "text": "\"Majonty Vote\" means the written approval of, or the affirmative vote by, Members holding a majority of the Member Votes."
  },
  {
    "id": "c021",
    "name": "Definition: Majority",
    "text": "\"Majority\" means a majority of the Member Votes,"
  },
  {
    "id": "c022",
    "name": "Definition: Manager",
    "text": "\"Manager\" means any Person designated by the Members as a manager of the Company within the meaning of the Maine Act and shall include the Directors of the Company."
  },
  {
    "id": "c023",
    "name": "Definition: Member",
    "text": "\"Member\" means each of LSB and DMSA and includes any Person admitted as an Additional Member or a substitute Member pursuant to the provisions of this Agreement, in such Person's capacity as a member of the Company, and \"Members\" means two (2) or more of such Persons when acting in their capacities as members of the Company. For purposes of the Maine Act, the Members shall constitute one (1) class or group of members."
  },
  {
    "id": "c024",
    "name": "Definition: Member Votes",
    "text": "\"Member Votes” means the votes allocated to each Person as reflected in Schedule A as may be amended."
  },
  {
    "id": "c025",
    "name": "Definition: Net Cash Flow",
    "text": "\"Net Cash Flow\" means, for each Fiscal Year or other period of the Company, the gross cash receipts of the Company from all sources, but excluding any amounts, such as gross receipts taxes, that are held by the Company as a collection agent or in trust for others or that are otherwise not unconditionally available to the Company, less all amounts paid by or for the account of the Company during the same Fiscal Year or other period (including, without limitation, payments of principal and interest on any Company indebtedness and expenses reimbursed to the Members under Section 5.2 hereof), and less any amounts determined by the Members to be necessary to provide a reasonable reserve for working-capital needs or any other contingencies of the Company. Net Cash Flow shall be determined in accordance with the cash receipts and disbursements method of accounting and otherwise in accordance with generally accepted accounting principles, consistently applied. Net Cash Flow shall not be reduced by depreciation, amortization, cost recovery deductions, depletion, similar allowances or ' other non-cash items, but shall be increased by any reduction of reserves previously established."
  },
  {
    "id": "c026",
    "name": "Definition: Officer",
    "text": "\"Officer\" means an officer of the Company."
  },
  {
    "id": "c027",
    "name": "Definition: Percentage Interest",
    "text": "“Percentage Interest” means the interest of a Member, expressed as a portion of one hundred percent, as shown on Schedule A hereto, which reflects the Member's ownership interest in the Company, as determined by the unanimous written consent of the Members as adjusted from time to time."
  },
  {
    "id": "c028",
    "name": "Definition: Person",
    "text": "\"Person\" includes any individual, Company, association, partnership (general or limited), joint venture, trust, estate, limited liability company, or other legal entity or organization."
  },
  {
    "id": "c029",
    "name": "Definition: Profits and Losses",
    "text": "“Profits” and \"Losses\" means, for each Fiscal Year, an amount equal to the Company's taxable income or loss for such Fiscal Year, determined in accordance with § 703{a) of the Code."
  },
  {
    "id": "c030",
    "name": "Definition: Secretary",
    "text": "\"Secretary\" means the Person appointed by the Board as the secretary of the Company, who shall perform the duties described in Section 7.4 of this Agreement."
  },
  {
    "id": "c031",
    "name": "Definition: Tax Matters Partner",
    "text": "\"Tax Matters Partner\" has the meaning set forth in Section 11.1 hereof."
  },
  {
    "id": "c032",
    "name": "Definition: Treasury Regulations",
    "text": "\"Treasury Regulations\" means the income tax regulations, including temporary regulations, promulgated under the Code, as such regulations may be amended from time to time (including corresponding provisions of succeeding regulations)."
  },
  {
    "id": "c033",
    "name": "Section 1.2 Headings",
    "text": "Section 1.2 Headings. The headings and subheadings in this Agreement are included for convenience and identification only and are in no way intended to describe, interpret, define or limit the scope, extent or intent of this Agreement or any provision hereof."
  },
  {
    "id": "c034",
    "name": "Section 2.1 Formation",
    "text": "Section 2.1 Formation. (1) The Members hereby form the Company as a limited liability company under and pursuant to the provisions of the Maine Act and agree that the nghts, duties, and liabilities of the Members shall be as provided in the Maine Act, except as otherwise provided herein. 4. (it) Upon the execution of this Agreement or a counterpart of this Agreement, LSB and DMSA shall be admitted as Members. (ii) | The name and mailing address of each Member, the agreed value of the amount contributed to the capital of the Company and the Percentage Interest of each Member shall be listed on Schedule A attached hereto. The Secretary shall be required to update Schedule A from time to time as necessary to accurately reflect the information therein. Any amendment or revision to Schedule A made in accordance with this Agreement shall not be deemed an amendment to this Agreement. Any reference in this Agreement to Schedule A shall be deemed to be a reference to Schedule A as amended and in effect from time to time. (iv) Gerry Pike, as an authorized person within the meaning of the Maine Act, shall execute, deliver, and file the Articles,"
  },
  {
    "id": "c035",
    "name": "Section 2.2 Name",
    "text": "Section 2.2. Name. The name of the Company formed hereby is Dialogo, LLC. The business of the Company may be conducted upon compliance with all applicable Laws under any other name designated by the Board."
  },
  {
    "id": "c036",
    "name": "Section 2.3 Term",
    "text": "Section 2.3 Term. The term of the Company shall commence on the date the Articles are filed in the office of the Secretary of State of the State of Maine and shall continue in perpetuity, unless the Company is dissolved in accordance with the provisions of this Agreement. The existence of the Company as a separate legal entity shall continue until cancellation of the Articles in the manner required by the Maine Act."
  },
  {
    "id": "c037",
    "name": "Section 2.4 Registered Agent and Office",
    "text": "Section2.4 — Registered Agent and Office. The Company's registered agent and office in the State of Maine shall be Mark Googins, Verrill & Dana, One Portland Square, Portland, Maine 04112. At any time, the Members may designate another registered agent and/or registered office,"
  },
  {
    "id": "c038",
    "name": "Section 2.5 Principal Place of Business",
    "text": "Section 2.5 Principal Place of Business. The principal place of business of the Company shall be at 252 Open Square Way, Suite 405, Holyoke, MA. 01040. At any time, the Board may change the location of the Company's principal place of business to another location."
  },
  {
    "id": "c039",
    "name": "Section 2.6 Qualification in Other Jurisdictions",
    "text": "Section 2.6 Qualification in Other Jurisdictions. The Board shall cause the Company to be qualified, formed, or registered under assumed or fictitious name statutes or similar Laws in any Jurisdiction in which the Company transacts business. The Secretary, as an authorized person within the meaning of the Maine Act, shall execute, deliver and file any certificates (and any amendments and/or restatements thereof) necessary for the Company to qualify to do business in a Jurisdiction in which the Company may wish to conduct business."
  },
  {
    "id": "c040",
    "name": "Section 3.1 Purpose",
    "text": "Section 3.1 Purpose. The Company is formed for the object and purpose of developing Spanish language newspaper(s) and media, and to engage in any lawful act or activity for which limited lability companies may be formed under the Maine Act and engaging in any and all activities necessary, convenient, desirable or incidental to the foregoing, including, without limitation, (i) to acquire, hold and dispose of the investments, including investments in Affiliates, (ii) to lend money to, borrow money from, act as surety, guarantor or endorser for, provide collateral for, and transact other business with third parties including, Members and Affiliates of the Company, and (iii) acquiring, holding, managing, operating and disposing of interests in real and personal property."
  },
  {
    "id": "c041",
    "name": "Section 3.2(i) Powers of the Company",
    "text": "Section 3.2 Powers of the Company. (i) The Company shall have the power and authority to take any and all actions necessary, appropniate, proper, advisable, incidental or convenient to or for the furtherance of the purpose set forth in Section 3.1, including, but not limited to, the power: (a) to conduct its business, carry on its operations and have and exercise the powers granted to a limited lability company by the Maine Act in any state, termtory, district or possession of the United States, or in any foreign country, that may be necessary, convenient, or incidental to the accomplishment of the purpose of the Company; (b) to enter into, perform and carry out contracts of any kind, including, without limitation, contracts with the Directors, the Officers, any Manager, any Member, any Affiliate thereof, or any agent or Affiliate of the Company necessary to, in connection with, convenient to, or incidental to the accomplishment of the purpose of the Company; (c) to lend money to, borrow money from, act as surety, guarantor or endorser for, provide collateral for, and transact other business with third parties including Members and Affiliates of the Company; (d) to purchase, take, receive, subscribe for, or otherwise acquire, own, hold, vote, use, employ, sell, mortgage, lend, pledge, or otherwise dispose of, and otherwise use and deal in and with, Interests or other interests in or obligations of -6- domestic or foreign Company's, associations, general or limited partnerships (including, without limitation, the power to be admitted as a partner thereof and to exercise the rights and perform the duties created thereby), trusts, limited liability companies (including, without limitation, the power to be admitted as a member or appointed as a manager thereof and to exercise the rights and perform the duties created thereof), or individuals or direct or indirect obligations of the United States or of any government, state, terntory, governmental district, or municipality or of any instrumentality of any of them; (e) to lend money for its proper purpose, to invest and reinvest its funds, to take and hold real and personal property for the payment of funds so loaned or invested; (f) to sue and be sued, complain and defend, and participate in administrative or other proceedings, in its name; (z) to appoint employees and agents of the Company, and define their duties and fix their compensation; (h) to indemnify any Person in accordance with the Maine Act and to obtain any and all types of insurance; (i) to cease its activities and cancel its Articles; (j) to negotiate, enter into, renegotiate, extend, renew, terminate, modify, amend, waive, execute, acknowledge, or take any other action with respect to any lease, contract or security agreement in respect of any assets of the Company; (k) to borrow money and issue evidences of indebtedness, and to secure the same by a mortgage, pledge, or other lien on the assets of the Company; () to pay, collect, compromise, liugate, arbitrate, or otherwise adjust or settle any and all other claims or demands of or against the Company or to hold such proceeds against the payment of contingent liabilities; and (m) to make, execute, acknowledge, and file any and all documents or instruments necessary, convenient, or incidental to the accomplishment of the purpose of the Company."
  },
  {
    "id": "c042",
    "name": "Section 3.2(ii) Merger",
    "text": "(ii) The Company may merge with, or consolidate into, another limited liability company or other business entity upon the approval of all of the Members."
  },
  {
    "id": "c043",
    "name": "Section 4.1(i) — Capital Contributions",
    "text": "(i) Each Member has contributed or is deemed to have contributed to the capital of the Company the amount set forth opposite the Member's name on Schedule A attached hereto. The agreed value of the Capital Contributions made or deemed to have been made by each Member shall be set forth on Schedule A."
  },
  {
    "id": "c044",
    "name": "Section 4.2 Member's Interest",
    "text": "Section 4.2 Member's Interest. A Member's Interest shall for all purposes be personal property. A Member has no interest in specific Company property."
  },
  {
    "id": "c045",
    "name": "Section 4.3 Status of Capital Contributions",
    "text": "Section 4.3 Status of Capital Contributions. (i) Except as otherwise provided in this Agreement, the amount of a Member's Capital Contributions may be retumed to it, in whole or in part, at any time, but only with the consent of all of the Members. Any such returns of Capital Contributions shall be made to all Members in proportion to their Percentage Interests. Notwithstanding the foregoing, no return of a Member's Capital Contributions shall be made hereunder if such distribution would violate applicable law. Under circumstances requiring a return of any Capital Contribution, no Member shall have the right to demand or receive property other than cash, except as may be specifically provided in this Agreement or as may be specifically agreed to by all of the Members. (il) No Member shall receive any interest, salary, or drawing with respect to its Capital Contributions or its Capital Account or for services rendered on behalf of the Company or otherwise in its capacity as a Member, except: (a) the respective invoices of each of DMSA, in connection with services rendered or goods provided through or on behalf of the Company for a client of the Company, shall be paid by the Company as it receives payment form such customer; (b) the Members shall be paid profits in accordance with their respective Membership Interests; and (c) as expressly provided by a unanimous resolution of the Board. (iti) Except as otherwise provided herein and by applicable law, the Members shall be able only to make their capital contributions pursuant to Section 4.1 hereof, and no Member shall be required to lend any funds to the Company or, after a Member's Capital Contributions have been fully paid pursuant to Section 4.1 hereof, to make any additional capital contributions to the Company. No Member shall have any personal liability for the repayment of any Capital Contribution of any other Member."
  },
  {
    "id": "c046",
    "name": "Section 4.4 Capital Accounts",
    "text": "Section 4.4 Capital Accounts. (i) An individual Capital Account shall be established and maintained for each Member. (it) The Capital Account of each Member shall be maintained in accordance with the provisions of Regulation section 1.704-1 (b) (2) (iv)"
  },
  {
    "id": "c047",
    "name": "Section 4.5 Advances",
    "text": "Section 4.5 Advances. If any Member shall advance any funds to the Company in excess of its Capital Contnbutions, the amount of such advance shall neither increase its Capital Account nor entitle it to any mcrease in its Interest of the distributions of the Company. The amount of any such advance shall be a debt obligation of the Company to such Member and shall be subject to such terms and conditions acceptable to the Company and each Member. Any such advance shall be payable and collectible only out of Company assets, and the other Members shall not be personally obligated to repay any part thereof. No Person who makes any nonrecourse loan to the Company shall have or acquire, as a result of making such loan, any direct or indirect interest in the profits, capital, or property of the Company, other than as a creditor."
  },
  {
    "id": "c048",
    "name": "Section 5.1 Powers of Members",
    "text": "Section 5.1 Powers of Members. The Members shal] have the power to exercise any and all rights or powers granted to the Members pursuant to the express terms of this Agreement. The Members shall also have the power to authorize the Board, by Majority Vote, to possess and exercise any right or power not already vested in the Board pursuant to Article VI or any other provision of this Agreement. In addition to the foregoing, the Members have the power to exercise any and all other rights or powers of the Company and to do all lawful acts and things as are not by the Maine Act or this Agreement directed or required to be exercised or done by the Board. Except as provided herein, individually, the Members shall have no power to bind the Company."
  },
  {
    "id": "c049",
    "name": "Section 5.2 Reimbursements",
    "text": "Section 5.2 | Reimbursements. The Company shall reimburse the Members, for all ordinary and necessary out-of pocket expenses incurred by the Members on behalf of the Company. Such reimbursement shall be treated as an expense of the Company that shall be deducted in computing the Net Cash Flow and shall not be deemed to constitute a distributive Interest of Profits or a distribution or return of capital to any Member."
  },
  {
    "id": "c050",
    "name": "Section 5.3 Partition",
    "text": "Section 5.3. Partition Each Member waives any and all rights that it may have to maintain an action for partition of the Company's property."
  },
  {
    "id": "c051",
    "name": "Section 5.4 Resignation",
    "text": "Section 5.4 Resignation A Member may not resign from the Company prior to the dissolution and winding up of the Company."
  },
  {
    "id": "c052",
    "name": "Section 5.5 Meetings of Members",
    "text": "Section 5.5 Meetings of Members. (i) The annual meeting of the Members for the election of Directors and the transaction of other business shall be held, in each year, at such place as shall be designated by the Board and stated in the notice of the meeting. Special meetings of Members for any purpose or purposes may be held at such time and place, and shall be stated in the notice of the meeting or in a duly executed waiver of notice thereof. (u) At the annual meeting of the Members, LSB shall elect one of the Directors and DMSA shall elect two of the Directors on the Company’s Board of Directors. (ut) Written notice of the annual meeting stating the place, date and hour of the meeting shall be given to each Member entitled to vote at such meeting not less than 10 nor more than 60 days before the date of the meeting. -10- Case 3:05-cv-30076-MAP Document 15-2 ~~ Filed 04/26/2005 Page 11 of 30 (iv) Special meetings of the Members, for any purpose or purposes, may be called by the President and shall be called by the President or Secretary at the request in writing of a majority of the Board. Such request shall state the purpose or purposes of the proposed meeting. (v) Written notice of a special meeting stating the place, date, and hour of the meeting and the purpose or purposes for which the meeting is called, shall be given not less than 10 nor more than 60 days before the date of the meeting, to each Member entitled to vote at such meeting. (v1) Business transacted at any special meeting of Members shall be limited to the purposes stated in the notice, unless otherwise agreed to by all of the Members. (vu) | A Majority present in person or by proxy, shall constitute a quorum at all meetings of the Members for the transaction of business except as otherwise provid ed by this Agreement. If, however, such quorum shall not be present or represented at any meeting of the Members, the Members entitled to vote thereat, present in person or represented by proxy, shall have power to adjoum the meeting from time to time, without notice other than announcement at the meeting, until a quorum shall be present or represented. At such adjourned meeting at which a quorum shall be present or represented any business may be transacted which might have been transacted at the meeting as originally notified. If the adjournment is for more than 30 days, or if after the adjournment a new record date is fixed for the adjourned meeting, a notice of the adjourned meeting shall be given to each Member of record entitled to vote at the meeting. (vii) | When a quorum is present at any meeting, a Majority Vote shall decide any question brought before such meeting, unless the question is one upon which by express provision of this Agreement, a different vote is required in which case such express provision shall govern and control the decision of such question. (ix) Unless otherwise provided in this Agreement, each Member shall at every meeting of the Members be entitled to vote in person or by proxy, but no proxy shall be voted on after three years from its date, unless the proxy provides for a longer period. (x) Members may participate in a meeting of the Members by means of conference telephone or similar communications equipment, provided all persons participating in the meeting can hear each other, and such participation in a meeting shall constitute presence in person at the meeting. If all the participants are participating by conference telephone or similar -ll- communications equipment, the meeting shall be deemed to be held at the principal place of business of the Company. (xi) | Unless otherwise provided in this Agreement, any action required to be taken at any annual or special meeting of the Members of the Company or any action which may be taken at any annual or special meeting of such Members, may be taken without a meeting, without prior notice and without a vote, if a consent in writing, setting forth the action so taken, shall be signed by a Majority. Prompt notice of taking of the action without a meeting by less than unanimous consent shall be given to those Members who have not consented in writing."
  },
  {
    "id": "c053",
    "name": "Section 6.1 Board of Directors",
    "text": "Section 6.1 Board of Directors. Subject to Section 5.1 of this Agreement, the business and affairs of the Company shall be managed by or under the direction of a Board of three Directors. A person elected as a Director is by such election designated a Manager by the Members for purposes of the Act. The Directors shall be elected at the annual meeting of the Members, except as provided in this Article, and each Director elected shall hold office until a successor is elected and qualified or until such Director's earlier death, resignation, or removal. Directors need not be Members. Vacancies shall be filled by the vote of LSB, if the vacancy is the LSB-elected Director, and by DMSA if the vacancy is a DMSA-elected director, and the Directors so chosen shall hold office until the next annual election and until their successors are duly elected and shall qualify, unless sooner displaced."
  },
  {
    "id": "c054",
    "name": "Section 6.2 Meetings of the Board of Directors",
    "text": "Section6.2 Meetings of the Board of Directors. The Board of Directors of the Company may hold meetings, both regular and special, within or outside the State of Maine. The first meeting of each newly elected Board of Directors shall be held immediately after the annual meeting of Members and at the same place, and no notice of such meeting shall be necessary to the newly elected Directors in order legally to constitute the meeting, provided a quorum shall be present. In the event such meeting is not held at that tume and place, the meeting may be held at such time and place as shall be specified in a notice given as hereinafter provided for special meetings of the Board of Directors, or as shall be specified in a written waiver signed by all of the Directors. Regular meetings of the Board may be held without notice at such time and at such place as shall from time to time be determined by the Board. Special meetings of the Board may be called by the President on three (3) days’ notice to each Director, either personally, by telephone, by mail, by telegram or by any other means of communication; special meetings shall be called by the President in like manner and on like notice on the written request of one or more of the Directors."
  },
  {
    "id": "c055",
    "name": "Section 6.3 Quorum and Acts of the Board",
    "text": "Section 6.3. Quorum and Acts of the Board. At all meetings of the Board a majority of the Directors shal! constitute a quorum for the transaction of business and, except as otherwise provided in Section 6.9 of this Agreement or any other provision of this Agreement, the act of a majonty of the Directors present at any meeting at which there is a quorum shall be the act of the Board. If any Directors’ vote shall result in a tie- vote, then the matter voted on by the Board shall be presented to the Members for vote, and the resulting vote by the Members shall decide such matters. If a quorum shall not be present at any meeting of the Board, the Directors present thereat may adjourn the meeting from time to time, without notice other than announcement at the meeting, until a quorum shall be present. Any action required or permitted to be taken at any meeting of the Board or of any committee thereof may be taken without a meeting, if all members of the Board or committee, as the case may be, consent thereto in writing, and the writing or writings are filed with the minutes of proceedings of the Board or committee."
  },
  {
    "id": "c056",
    "name": "Section 6.4 Electronic Communications",
    "text": "Section 6.4 — Electronic Communications. Members of the Board, or any committee designated by the Board, may participate in a meeting of the Board, or any committee, by means of conference telephone or similar communications equipment by means of which all persons participating in the meeting can hear each other, and such participation in a meeting shall constitute presence in person at the meeting. If all the participants are participating by conference telephone or similar communications equipment, the meeting shall be deemed to be held at the principal place of business of the Company."
  },
  {
    "id": "c057",
    "name": "Section 6.5 Committees of Directors",
